<?php
require __DIR__.'/functions.php';
try{$user=currentUser();$dbOk=true;}catch(Throwable $e){$user=null;$dbOk=false;error_log($e->getMessage());}
$games=games();$favorites=[];
function mediaImage(string $dir,string $stem):?string{foreach(['png','jpg','jpeg'] as $ext){$path=__DIR__."/$dir/$stem.$ext";if(is_file($path))return implode('/',array_map('rawurlencode',explode('/',$dir))).'/'.rawurlencode($stem).'.'.$ext;}return null;}
$iconImages=[];foreach(['consolas','juegos','favoritos','cuenta','ajustes'] as $key)$iconImages[$key]=mediaImage('icons',$key);
$bannerImages=[];foreach(array_keys(consoles()) as $key)$bannerImages[$key]=mediaImage('banner consol',$key);

if($user){try{$q=db()->prepare('SELECT game_id FROM favorites WHERE user_id=?');$q->execute([$user['id']]);$favorites=$q->fetchAll(PDO::FETCH_COLUMN);}catch(Throwable $e){error_log($e->getMessage());}}
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ending · XMB</title><style>
:root{color-scheme:dark;--red:#fa3449;--step:142px}*{box-sizing:border-box}body{margin:0;background:#030305;color:#f6f0f0;font-family:Segoe UI,Arial,sans-serif;overflow:hidden}body:before{content:"";position:fixed;inset:0;background:radial-gradient(ellipse at 72% 70%,#7c0c225c,transparent 58%),radial-gradient(ellipse at 22% 105%,#6c071e6b,transparent 50%),linear-gradient(115deg,#020205,#0b070d 65%,#030205);z-index:-3}.wave{position:fixed;left:-30%;bottom:-25%;height:65%;width:170%;border-top:2px solid #e6384b75;border-radius:50%;transform:rotate(-9deg);box-shadow:0 -28px 65px #8d102435;animation:wave 8s ease-in-out infinite alternate;pointer-events:none;z-index:-2}.wave.b{bottom:-30%;border-color:#fd647c40;animation-delay:-3s;transform:rotate(-5deg)}@keyframes wave{to{translate:0 -38px;scale:1.02}}.top{position:absolute;top:5%;left:5%;right:5%;display:flex;align-items:center;justify-content:space-between;z-index:10}.brand{font-weight:700;letter-spacing:.38em;font-size:18px}.brand b{color:var(--red)}.topright{display:flex;align-items:center;gap:16px;color:#cbbfc2;font-size:12px}.topright img{width:35px;height:35px;object-fit:cover;border-radius:50%;border:1px solid #7e3344}.clock{font-variant-numeric:tabular-nums}.stage{position:absolute;inset:0;overflow:hidden}.horizontal{position:absolute;left:27%;top:23%;height:142px;display:flex;align-items:center;transition:transform .52s cubic-bezier(.2,.8,.15,1);will-change:transform}.category{width:var(--step);flex:0 0 var(--step);border:0;background:none;color:#a79da0;display:flex;flex-direction:column;align-items:center;gap:9px;cursor:pointer;transition:transform .42s,opacity .42s,filter .42s;opacity:.56;filter:grayscale(.5);font:inherit}.category .art{width:70px;height:70px;display:grid;place-items:center;transition:transform .4s,filter .4s}.category svg{width:57px;height:57px;filter:drop-shadow(0 3px 7px #0008);transition:color .35s,filter .35s}.category.selected svg{color:#fff;filter:drop-shadow(0 0 10px #ff344b99)}.category span{font-size:13px;white-space:nowrap}.category.selected{opacity:1;color:white;filter:none;transform:scale(1.25)}.category.selected .art{filter:drop-shadow(0 0 7px #e22b4d60)}.category.selected span{text-shadow:0 0 9px #ef344a77}.vertical{position:absolute;left:calc(27% + 71px);top:calc(23% + 165px);width:min(65vw,620px);transition:opacity .22s,transform .35s;opacity:1}.vertical.out{opacity:0;transform:translateY(20px)}.item{height:69px;display:flex;align-items:center;gap:18px;cursor:pointer;border:0;background:none;color:#b0a4aa;text-align:left;font:inherit;font-size:19px;width:100%;transition:transform .32s,opacity .32s,color .32s;opacity:.55}.item .small{height:37px;width:37px;display:grid;place-items:center;color:#e27b8a;font-size:24px;font-weight:300}.item.active{color:#fff;opacity:1;transform:translateX(17px) scale(1.07);text-shadow:0 0 20px #f34c6580}.item.active .small{color:#ff3f5d}.item.active:after{content:'›';color:#ff4b66;margin-left:auto;font-size:27px}.item:hover{opacity:1}.detail{position:absolute;left:61%;top:48%;width:33%;max-height:37%;overflow:auto;padding:12px 8px 12px 25px;border-left:1px solid #aa34434d;opacity:0;transform:translateX(18px);transition:opacity .35s,transform .35s;pointer-events:none}.detail.visible{opacity:1;transform:none}.detail h2{font-size:22px;font-weight:400;margin:0 0 12px}.detail p{font-size:13px;color:#c3b5b8;line-height:1.7}.covers{display:flex;gap:9px;overflow:auto;padding-bottom:10px}.covers img{height:115px;width:85px;object-fit:cover;background:#1b1015}.avatars{display:flex;flex-wrap:wrap;gap:8px}.avatars img{height:52px;width:52px;object-fit:cover;border:1px solid #6e3341}.hint{position:absolute;bottom:4%;left:5%;right:5%;display:flex;justify-content:space-between;gap:10px;color:#b8a9af;font-size:12px}.hint b{color:#fa6275}.toast{position:fixed;bottom:14%;left:50%;transform:translateX(-50%);background:#210d17;border:1px solid #a43149;padding:12px 20px;z-index:30;font-size:13px}.title{position:absolute;left:5%;top:16%;color:#a6949c;font-size:11px;letter-spacing:.3em}.mobile-nav{display:none}@media(max-width:750px){:root{--step:105px}.horizontal{left:calc(50% - 52px);top:20%;height:115px}.category svg{width:50px;height:50px}.category .art{height:55px;width:55px}.category span{font-size:11px}.vertical{left:8%;top:43%;width:85%}.item{height:51px;font-size:16px}.detail{display:none}.topright .clock{display:none}.hint{bottom:13%;font-size:10px}.mobile-nav{display:flex;position:absolute;bottom:2%;left:8%;right:8%;justify-content:space-between;gap:8px}.mobile-nav button{border:1px solid #8e2c3f;background:#250d18;color:white;border-radius:6px;font-size:21px;padding:8px 16px}}

.category svg{width:54px;height:54px;stroke-width:1.8;filter:none}.category.selected svg{filter:drop-shadow(0 0 9px #ec34475e)}.item .small svg{width:27px;height:27px;stroke-width:1.8}.vertical{max-height:52vh;overflow-y:auto;scrollbar-width:none}.vertical::-webkit-scrollbar{display:none}.detail{top:43%;max-height:48%;pointer-events:auto}.panel{position:fixed;inset:0;z-index:40;background:#030306df;display:none;align-items:center;justify-content:center;padding:20px;backdrop-filter:blur(14px)}.panel.show{display:flex}.modal{width:min(520px,96vw);max-height:90vh;overflow:auto;background:#130c13;border:1px solid #7a293d;border-radius:16px;padding:28px;box-shadow:0 25px 90px #000a}.modal h2{font-weight:400}.modal input{display:block;width:100%;margin:12px 0;background:#08070b;color:white;border:1px solid #5a3440;border-radius:7px;padding:12px}.modal button,.action{border:1px solid #96394f;background:#34101e;color:#fff;border-radius:7px;padding:11px 16px;cursor:pointer;margin:5px}.modal button:hover,.action:hover{background:#742238}.game-row{display:flex;gap:12px;align-items:center;padding:8px 0;border-bottom:1px solid #ffffff12}.game-row .action{font-size:12px;padding:7px}.game-row span{flex:1;font-size:13px}.detail .action{pointer-events:auto}.detail p{margin-bottom:10px}.avatarpick{display:grid;grid-template-columns:repeat(6,1fr);gap:8px}.avatarpick img{width:100%;aspect-ratio:1;object-fit:cover;cursor:pointer;border-radius:8px;border:2px solid transparent}.avatarpick img:hover{border-color:#ff4c6d}@media(max-width:750px){.detail{display:block;position:absolute;top:70%;left:8%;width:85%;max-height:18%;font-size:12px}.detail .covers{display:none}.modal{padding:18px}}

:root{--accent2:#501027;--red-soft:#45111f;--red-glow:#9d223c;--wave2:#54122c}.cat-icon{height:58px;width:58px;object-fit:contain;filter:drop-shadow(0 3px 9px #0009)}.category.selected .cat-icon{filter:drop-shadow(0 0 12px var(--red-glow))}.category.selected span,.item.active .small{color:var(--red)}.wave{border-color:var(--red-glow);box-shadow:0 -28px 65px var(--red-soft)}.wave.b{border-color:var(--wave2)}.item.active:after{color:var(--red)}.console-banner{position:absolute;left:61%;top:38%;width:33%;height:39%;display:flex;align-items:center;justify-content:center;opacity:0;transform:translateX(24px);transition:opacity .5s ease,transform .5s ease;pointer-events:none}.console-banner.visible{opacity:1;transform:translateX(0)}.console-banner img{max-width:100%;max-height:100%;object-fit:contain;filter:drop-shadow(0 12px 30px #0008)}.modal input[type=color]{height:55px;padding:4px;cursor:pointer}@media(max-width:750px){.console-banner{left:52%;top:48%;width:42%;height:20%;opacity:0}.console-banner img{max-height:100%}.cat-icon{width:48px;height:48px}}
</style></head><body>
<div class="wave"></div><div class="wave b"></div><header class="top"><div class="brand">END<b>ING</b><small style="font-size:10px;letter-spacing:.15em;color:#a99ca1"> / XMB</small></div><div class="topright"><span class="clock" id="clock"></span><span id="userlabel"><?=h($user['username']??'Invitado')?></span><img id="useravatar" src="assets/avatars/avatar<?= (int)($user['avatar']??1) ?>.jpg" alt="Avatar"></div></header>
<div class="title">ENDING / SISTEMA RETRO</div><div id="consoleBanner" class="console-banner" aria-hidden="true"></div><main class="stage"><nav class="horizontal" id="horizontal" aria-label="Categorías"></nav><div class="vertical" id="vertical" aria-label="Opciones"></div><aside class="detail" id="detail"></aside></main><footer class="hint"><span><b>← →</b> Categorías &nbsp; <b>↑ ↓</b> Opciones &nbsp; <b>Enter</b> Abrir &nbsp; <b>Esc</b> Volver</span><span>ENDING v1.0 · PHP + MYSQL</span></footer>
<div class="mobile-nav"><button onclick="moveCat(-1)">←</button><button onclick="moveItem(-1)">↑</button><button onclick="preview()">●</button><button onclick="moveItem(1)">↓</button><button onclick="moveCat(1)">→</button></div>
<div class="panel" id="panel" role="dialog" aria-modal="true"><div class="modal"><button style="float:right" onclick="closePanel()" aria-label="Cerrar">✕</button><div id="panelcontent"></div></div></div>
<script>
const iconImages=<?=json_encode($iconImages,JSON_UNESCAPED_SLASHES|JSON_HEX_TAG)?>;
const bannerImages=<?=json_encode($bannerImages,JSON_UNESCAPED_SLASHES|JSON_HEX_TAG)?>;
const games=<?=json_encode($games,JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>;
let user=<?=json_encode($user,JSON_UNESCAPED_UNICODE|JSON_HEX_TAG)?>;
let favorites=new Set(<?=json_encode($favorites)?>);
const csrf=<?=json_encode(csrf())?>;
const paths={"home": "<path d=\"m8 19 16-13 16 13v20H8z\"/><path d=\"M19 39V26h10v13\"/>", "console": "<rect x=\"9\" y=\"12\" width=\"30\" height=\"25\" rx=\"3\"/><path d=\"M15 20h9m-4.5-4.5v9\"/><circle cx=\"30\" cy=\"21\" r=\"1.5\"/><circle cx=\"34\" cy=\"26\" r=\"1.5\"/>", "games": "<path d=\"M14 17h20c5 0 8 4 10 14 1 6-3 9-7 6l-7-6H18l-7 6c-4 3-8 0-7-6 2-10 5-14 10-14z\"/><path d=\"M13 24h10m-5-5v10\"/><circle cx=\"31\" cy=\"24\" r=\"1.5\"/><circle cx=\"36\" cy=\"28\" r=\"1.5\"/>", "heart": "<path d=\"M24 40 7 24C-2 15 11 3 22 15l2 2 2-2C37 3 50 15 41 24z\"/>", "user": "<circle cx=\"24\" cy=\"15\" r=\"8\"/><path d=\"M9 41v-4c0-9 6-14 15-14s15 5 15 14v4\"/>", "settings": "<circle cx=\"24\" cy=\"24\" r=\"8\"/><path d=\"M21 5h6l1 5 5 2 5-2 4 5-3 4 1 6 4 3-3 6-5-1-4 4-1 5h-7l-1-5-5-2-5 2-4-5 3-4-1-6-4-3 3-6 5 1 4-4z\"/>"};
function icon(name){return `<svg viewBox="0 0 48 48" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]}</svg>`}
const cats=[{name:'Consolas',icon:'console',items:['NES','SNES','Nintendo 64','Game Boy','Game Boy Color','Game Boy Advance','PlayStation 1','Mega Drive']},{name:'Juegos',icon:'games',items:['Catálogo','Buscar juegos','Reproductor']},{name:'Favoritos',icon:'heart',items:['Mis favoritos']},{name:'Cuenta',icon:'user',items:['Mi perfil','Iniciar sesión','Registrarse','Cambiar avatar','Cambiar nombre','Cerrar sesión']},{name:'Ajustes',icon:'settings',items:['Apariencia','Controles','Información']}];
const consoleKeys=['nes','snes','n64','gb','gbc','gba','psx','segaMD'];
let ci=0,ii=0,timer,bannerTimer;const defaultTheme=['#fa3449','#501027'];const $=id=>document.getElementById(id);
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function categoryArt(c){const k={Consolas:'consolas',Juegos:'juegos',Favoritos:'favoritos',Cuenta:'cuenta',Ajustes:'ajustes'}[c.name];return iconImages[k]?`<img class="cat-icon" src="${iconImages[k]}" alt="" onerror="this.replaceWith(document.createTextNode('◇'))">`:icon(c.icon)}
function renderCat(){let h=$('horizontal');h.innerHTML=cats.map((c,i)=>`<button class="category ${i===ci?'selected':''}" onclick="setCat(${i})"><div class="art">${categoryArt(c)}</div><span>${c.name}</span></button>`).join('');h.style.transform=`translateX(calc(${-ci} * var(--step)))`}
function scheduleBanner(){clearTimeout(bannerTimer);const el=$('consoleBanner');el.classList.remove('visible');el.replaceChildren();if(ci!==0)return;const key=consoleKeys[ii],src=bannerImages[key];if(!src)return;bannerTimer=setTimeout(()=>{if(ci!==0||consoleKeys[ii]!==key||$('panel').classList.contains('show'))return;const im=document.createElement('img');im.src=src;im.alt='Banner de '+cats[0].items[ii];el.replaceChildren(im);el.classList.add('visible')},3000)}
function renderItems(){const v=$('vertical');v.innerHTML=cats[ci].items.map((name,i)=>`<button class="item ${ii===i?'active':''}" onclick="setItem(${i})"><span class="small">${i===ii?'◆':'◇'}</span><span>${name}</span></button>`).join('');renderDetail();scheduleBanner()}
function listGames(items){return items.length?items.slice(0,12).map(g=>`<div class="game-row"><span>${escapeHtml(g.name)} <small>· ${escapeHtml(g.label)}</small></span><button class="action" onclick="location.href='play.php?id=${encodeURIComponent(g.id)}'">Jugar</button><button class="action" onclick="toggleFavorite('${g.id}')">${favorites.has(g.id)?'♥':'♡'}</button></div>`).join(''):'<p>No hay juegos todavía. Añade ROMs a las carpetas indicadas en el README.</p>'}
function renderDetail(){const name=cats[ci].items[ii];let content=`<h2>${escapeHtml(name)}</h2>`;if(ci===0)content+='<p>Selecciona esta consola para ver sus juegos. Si existe un banner, aparecerá después de 3 segundos.</p>';else if(ci===1)content+=name==='Catálogo'?listGames(games):'<p>Pulsa Enter para abrir esta opción.</p>';else if(ci===2)content+=user?listGames(games.filter(g=>favorites.has(g.id))):'<p>Inicia sesión para guardar tus favoritos.</p>';else if(ci===3)content+=`<p>${user?'Conectado como '+escapeHtml(user.username):'Inicia sesión o crea una cuenta para personalizar tu perfil.'}</p>`;else if(ci===4)content+=name==='Apariencia'?'<p>Selecciona dos colores para personalizar el entorno de Ending.</p>':'<p>Navega con teclado, ratón o mando compatible.</p>';const d=$('detail');d.innerHTML=content;d.classList.toggle('visible',ci!==0)}
function setCat(i){clearTimeout(bannerTimer);$('consoleBanner').classList.remove('visible');if(i<0||i>=cats.length)return;ci=i;ii=0;renderCat();const v=$('vertical');v.classList.add('out');clearTimeout(timer);timer=setTimeout(()=>{renderItems();v.classList.remove('out')},160)}function moveCat(d){setCat(ci+d)}function setItem(i){if(i<0||i>=cats[ci].items.length)return;ii=i;renderItems()}function moveItem(d){setItem(ii+d)}
function showPanel(content){clearTimeout(bannerTimer);$('consoleBanner').classList.remove('visible');$('panelcontent').innerHTML=content;$('panel').classList.add('show')}
function closePanel(){$('panel').classList.remove('show');scheduleBanner()}
async function api(action,data={}){const fd=new FormData();fd.append('action',action);fd.append('csrf',csrf);for(const [k,v] of Object.entries(data))fd.append(k,v);try{const r=await fetch('api.php',{method:'POST',body:fd,credentials:'same-origin'});return await r.json()}catch{return {ok:false,message:'No se pudo conectar con el servidor'}}}
function form(mode){showPanel(`<h2>${mode==='login'?'Iniciar sesión':'Crear cuenta'}</h2><form id="authform"><input name="username" autocomplete="username" placeholder="Usuario" required maxlength="24"><input name="password" type="password" autocomplete="${mode==='login'?'current-password':'new-password'}" placeholder="Contraseña" minlength="8" required><button>Continuar</button></form><p id="msg"></p>`);$('authform').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const r=await api(mode,Object.fromEntries(f));$('msg').textContent=r.message;if(r.ok)location.reload()}}
function preview(){const name=cats[ci].items[ii];if(ci===3){if(name==='Iniciar sesión')return form('login');if(name==='Registrarse')return form('register');if(name==='Cerrar sesión')return api('logout').then(()=>location.reload());if(!user)return form('login');if(name==='Cambiar avatar'){showPanel('<h2>Selecciona avatar</h2><div class="avatarpick">'+Array.from({length:12},(_,i)=>`<img src="assets/avatars/avatar${i+1}.jpg" alt="Avatar ${i+1}" onclick="setAvatar(${i+1})">`).join('')+'</div>');return}if(name==='Cambiar nombre'){showPanel('<h2>Cambiar nombre</h2><form id="renameform"><input name="username" maxlength="24" placeholder="Nuevo nombre" required><button>Guardar</button></form><p id="msg"></p>');$('renameform').onsubmit=async e=>{e.preventDefault();let r=await api('rename',{username:e.target.username.value});$('msg').textContent=r.message;if(r.ok)location.reload()};return}showPanel(`<h2>Mi perfil</h2><p>${escapeHtml(user.username)}</p>`);return}
if(ci===4&&name==='Apariencia'){showThemePanel();return}if(ci===1&&name==='Buscar juegos'){showPanel('<h2>Buscar juegos</h2><input id="search" placeholder="Nombre del juego"><div id="results"></div>');$('search').oninput=()=>{$('results').innerHTML=listGames(games.filter(g=>g.name.toLowerCase().includes($('search').value.toLowerCase())))};$('search').oninput();return}if(ci===0||ci===1||ci===2){showPanel(`<h2>${escapeHtml(name)}</h2><div style="max-height:60vh;overflow:auto">${listGames(ci===0?games.filter(g=>g.console===consoleKeys[ii]):ci===2?games.filter(g=>favorites.has(g.id)):games)}</div>`);return}showPanel(`<h2>${escapeHtml(name)}</h2><p>Ending XMB — sistema retro en desarrollo.</p>`)}
async function toggleFavorite(id){if(!user){form('login');return}let r=await api('favorite',{game:id});if(r.ok){r.favorite?favorites.add(id):favorites.delete(id);renderDetail();if($('panel').classList.contains('show'))preview()}else alert(r.message)}
async function setAvatar(avatar){let r=await api('avatar',{avatar});if(r.ok)location.reload();else alert(r.message)}
function safeColor(v){return /^#[0-9a-f]{6}$/i.test(v)?v:'#fa3449'}
function hexRgb(h){return [1,3,5].map(i=>parseInt(h.slice(i,i+2),16))}
function mix(a,b,t){const x=hexRgb(a),y=hexRgb(b);return '#'+x.map((v,i)=>Math.round(v*(1-t)+y[i]*t).toString(16).padStart(2,'0')).join('')}
function applyTheme(){let colors;try{colors=JSON.parse(localStorage.getItem('ending-theme')||'null')}catch{}if(!Array.isArray(colors)||colors.length!==2)colors=defaultTheme;const [a,b]=colors.map(safeColor);document.documentElement.style.setProperty('--red',a);document.documentElement.style.setProperty('--accent2',b);document.documentElement.style.setProperty('--red-soft',mix(a,'#08080c',.65));document.documentElement.style.setProperty('--red-glow',mix(a,'#08080c',.4));document.documentElement.style.setProperty('--wave2',mix(b,'#08080c',.25));return [a,b]}
function showThemePanel(){const colors=applyTheme();showPanel(`<h2>Personalizar entorno</h2><p>Elige dos colores desde el círculo cromático de tu navegador.</p><label>Color principal <input type="color" id="themeA" value="${colors[0]}"></label><label>Color secundario <input type="color" id="themeB" value="${colors[1]}"></label><button id="themeReset">Restablecer negro y rojo</button><p>Los cambios se guardan en este navegador.</p>`);const update=()=>{localStorage.setItem('ending-theme',JSON.stringify([$('themeA').value,$('themeB').value]));applyTheme()};$('themeA').oninput=update;$('themeB').oninput=update;$('themeReset').onclick=()=>{localStorage.removeItem('ending-theme');applyTheme();showThemePanel()}}
let padPrev={},padLast=0,padRepeat=0;
function startGamepad(){if(!navigator.getGamepads)return;function frame(t){if(document.hidden){requestAnimationFrame(frame);return}const pads=Array.from(navigator.getGamepads()||[]).filter(Boolean);const pad=pads[0];if(pad){const pressed=i=>!!pad.buttons[i]?.pressed;const axis=(i)=>pad.axes[i]||0;const dir=pressed(14)||axis(0)<-.55?'left':pressed(15)||axis(0)>.55?'right':pressed(12)||axis(1)<-.55?'up':pressed(13)||axis(1)>.55?'down':null;if(dir&&(dir!==padPrev.dir||t-padRepeat>220)){if(!$('panel').classList.contains('show'))({left:()=>moveCat(-1),right:()=>moveCat(1),up:()=>moveItem(-1),down:()=>moveItem(1)})[dir]();padRepeat=t}const confirm=pressed(0),back=pressed(1);if(confirm&&!padPrev.confirm){if(!$('panel').classList.contains('show'))preview()}if(back&&!padPrev.back){if($('panel').classList.contains('show'))closePanel();else setCat(0)}padPrev={dir,confirm,back}}else padPrev={};requestAnimationFrame(frame)}requestAnimationFrame(frame)}
document.addEventListener('keydown',e=>{if($('panel').classList.contains('show')){if(e.key==='Escape')closePanel();return}if(['INPUT','TEXTAREA'].includes(document.activeElement.tagName))return;const f={ArrowLeft:()=>moveCat(-1),ArrowRight:()=>moveCat(1),ArrowUp:()=>moveItem(-1),ArrowDown:()=>moveItem(1),Enter:preview,Escape:()=>setCat(0)}[e.key];if(f){e.preventDefault();f()}});$('panel').addEventListener('click',e=>{if(e.target===$('panel'))closePanel()});function tick(){let d=new Date();$('clock').textContent=d.toLocaleDateString('es',{day:'2-digit',month:'short'})+' · '+d.toLocaleTimeString('es',{hour:'2-digit',minute:'2-digit'})}tick();setInterval(tick,30000);applyTheme();renderCat();renderItems();startGamepad();
</script></body></html>